/* Strict display override prevention */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b1f1d;
  --card-bg: #fff8eb;
  --crust-color: #c97d39;
  --accent-red: #d13028;
  --accent-dark: #1f140e;
  --focus-ring: #2660a4;
  --border-radius: 0px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  image-rendering: pixelated;
}

body {
  background-color: var(--bg-color);
  background-image: 
    radial-gradient(#3a2926 15%, transparent 16%),
    radial-gradient(#3a2926 15%, transparent 16%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  color: var(--accent-dark);
  font-family: "Courier New", Courier, monospace, system-ui;
  font-size: 16px;
  line-height: 1.4;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background-color: var(--card-bg);
  width: 100%;
  max-width: 480px;
  min-width: 320px;
  border: 4px solid var(--accent-dark);
  box-shadow: 6px 6px 0px 0px var(--accent-dark);
  padding: 24px;
}

.card-header {
  text-align: center;
  margin-bottom: 20px;
  border-bottom: 3px dashed var(--accent-dark);
  padding-bottom: 12px;
}

.title {
  font-size: 28px;
  letter-spacing: 2px;
  color: var(--accent-red);
  text-shadow: 2px 2px 0px #00000020;
}

.tagline {
  font-size: 14px;
  color: #6d5448;
  margin-top: 4px;
}

.pizza-preview-area {
  display: flex;
  justify-content: center;
  align-items: center;
  margin-bottom: 20px;
  background: #f4e8d3;
  border: 3px solid var(--accent-dark);
  padding: 12px;
}

#pizzaCanvas {
  width: 160px;
  height: 160px;
}

.section-group {
  border: 2px solid var(--accent-dark);
  padding: 12px;
  margin-bottom: 16px;
  background: #ffffff;
}

.section-title {
  font-weight: bold;
  font-size: 16px;
  padding: 0 6px;
  color: var(--accent-dark);
}

.radio-group {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-top: 6px;
}

.checkbox-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
  margin-top: 6px;
}

.pixel-choice {
  position: relative;
  display: block;
  cursor: pointer;
  user-select: none;
}

.pixel-choice input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.choice-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #fff8eb;
  border: 2px solid var(--accent-dark);
  padding: 8px 4px;
  text-align: center;
  transition: background 0.1s ease;
}

.choice-box .name {
  font-weight: bold;
  font-size: 14px;
}

.choice-box .cost {
  font-size: 12px;
  color: #6d5448;
}

/* Interactive states */
.pixel-choice:hover .choice-box {
  background: #faebd2;
}

.pixel-choice input:focus-visible + .choice-box {
  outline: 3px solid var(--focus-ring);
  outline-offset: 1px;
}

.pixel-choice input:checked + .choice-box {
  background: var(--crust-color);
  color: #ffffff;
  box-shadow: inset 2px 2px 0px 0px rgba(0,0,0,0.3);
}

.pixel-choice input:checked + .choice-box .cost {
  color: #fff2e0;
}

.refusal-msg {
  background-color: var(--accent-red);
  color: #ffffff;
  font-weight: bold;
  font-size: 14px;
  padding: 6px 8px;
  text-align: center;
  border: 2px solid var(--accent-dark);
  margin-top: 4px;
  margin-bottom: 10px;
}

.price-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 20px;
  font-weight: bold;
  padding: 12px;
  background: #f4e8d3;
  border: 3px solid var(--accent-dark);
  margin-bottom: 16px;
}

.total-amount {
  color: var(--accent-red);
}

.order-btn,
.secondary-btn {
  width: 100%;
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  padding: 12px;
  border: 3px solid var(--accent-dark);
  cursor: pointer;
  box-shadow: 4px 4px 0px 0px var(--accent-dark);
  transition: transform 0.05s ease, box-shadow 0.05s ease;
}

.order-btn {
  background-color: var(--accent-red);
  color: #ffffff;
}

.secondary-btn {
  background-color: var(--crust-color);
  color: #ffffff;
  margin-top: 16px;
}

.order-btn:hover,
.secondary-btn:hover {
  filter: brightness(1.1);
}

.order-btn:focus-visible,
.secondary-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.order-btn:active,
.secondary-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0px 0px var(--accent-dark);
}

/* Receipt / Summary */
.order-summary {
  margin-top: 20px;
  padding: 16px;
  background: #ffffff;
  border: 3px solid var(--accent-dark);
  box-shadow: 4px 4px 0px 0px var(--accent-dark);
}

.summary-title {
  font-size: 20px;
  text-align: center;
  margin-bottom: 12px;
  border-bottom: 2px dashed var(--accent-dark);
  padding-bottom: 8px;
}

.receipt-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 8px;
}

.toppings-row {
  flex-direction: column;
}

.receipt-list {
  list-style: square inside;
  margin-top: 4px;
  margin-left: 8px;
  color: #555;
}

.receipt-divider {
  border: none;
  border-top: 2px dashed var(--accent-dark);
  margin: 12px 0;
}

.total-row {
  font-size: 18px;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .radio-group {
    grid-template-columns: 1fr;
  }
  .checkbox-grid {
    grid-template-columns: 1fr;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('pizzaForm');
  const sizeRadios = document.querySelectorAll('input[name="pizzaSize"]');
  const toppingCheckboxes = document.querySelectorAll('input[name="topping"]');
  const refusalMsg = document.getElementById('toppingsRefusal');
  const totalPriceEl = document.getElementById('totalPrice');
  const orderSummary = document.getElementById('orderSummary');
  const summarySize = document.getElementById('summarySize');
  const summaryToppings = document.getElementById('summaryToppings');
  const summaryTotal = document.getElementById('summaryTotal');
  const newOrderBtn = document.getElementById('newOrderBtn');
  const canvas = document.getElementById('pizzaCanvas');
  const ctx = canvas.getContext('2d');

  const TOPPING_PRICE = 1.50;
  const MAX_TOPPINGS = 5;
  let refusalTimeout = null;

  // Topping coordinates preset for pixel visualization
  const TOPPING_OFFSETS = [
    [0, 0],
    [-20, -18], [22, -15], [-16, 22], [18, 20],
    [-35, 5], [30, 2], [2, -32], [0, 32],
    [-18, -2], [16, 2], [-2, 16], [4, -16]
  ];

  function getSelectedSize() {
    const checked = document.querySelector('input[name="pizzaSize"]:checked');
    return {
      name: checked.value,
      price: parseFloat(checked.getAttribute('data-price'))
    };
  }

  function getSelectedToppings() {
    return Array.from(document.querySelectorAll('input[name="topping"]:checked'));
  }

  function calculateTotal() {
    const size = getSelectedSize();
    const toppings = getSelectedToppings();
    const total = size.price + (toppings.length * TOPPING_PRICE);
    totalPriceEl.textContent = `$${total.toFixed(2)}`;
    return total;
  }

  function drawPixelPizza() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const centerX = 80;
    const centerY = 80;
    const size = getSelectedSize().name;
    let radius = 55;
    if (size === 'Small') radius = 45;
    if (size === 'Large') radius = 65;

    // Crust outer
    ctx.fillStyle = '#b06020';
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius + 8, 0, Math.PI * 2);
    ctx.fill();

    // Crust main
    ctx.fillStyle = '#e8a04c';
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius + 4, 0, Math.PI * 2);
    ctx.fill();

    // Sauce
    ctx.fillStyle = '#c72b22';
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius - 2, 0, Math.PI * 2);
    ctx.fill();

    // Cheese
    ctx.fillStyle = '#fce570';
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius - 6, 0, Math.PI * 2);
    ctx.fill();

    // Render toppings
    const selectedToppings = getSelectedToppings();
    selectedToppings.forEach((topInput, tIndex) => {
      const color = topInput.getAttribute('data-color') || '#222';
      ctx.fillStyle = color;
      const count = 4;
      for (let i = 0; i < count; i++) {
        const offsetIdx = (tIndex * count + i) % TOPPING_OFFSETS.length;
        const [ox, oy] = TOPPING_OFFSETS[offsetIdx];
        // Scale offsets based on pizza size
        const scale = radius / 65;
        const px = Math.round(centerX + ox * scale);
        const py = Math.round(centerY + oy * scale);
        ctx.fillRect(px - 4, py - 4, 8, 8);
      }
    });
  }

  // Handle size change
  sizeRadios.forEach(radio => {
    radio.addEventListener('change', () => {
      calculateTotal();
      drawPixelPizza();
    });
  });

  // Handle toppings toggle with max-5 limit
  toppingCheckboxes.forEach(checkbox => {
    checkbox.addEventListener('click', (e) => {
      const selectedCount = getSelectedToppings().length;
      if (checkbox.checked && selectedCount > MAX_TOPPINGS) {
        e.preventDefault();
        checkbox.checked = false;
        showRefusal();
        return;
      }
      calculateTotal();
      drawPixelPizza();
    });
  });

  function showRefusal() {
    refusalMsg.removeAttribute('hidden');
    if (refusalTimeout) {
      clearTimeout(refusalTimeout);
    }
    refusalTimeout = setTimeout(() => {
      refusalMsg.setAttribute('hidden', '');
    }, 2500);
  }

  // Handle Order button
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const size = getSelectedSize();
    const toppings = getSelectedToppings();
    const total = calculateTotal();

    summarySize.textContent = `${size.name} ($${size.price.toFixed(2)})`;
    summaryToppings.innerHTML = '';
    if (toppings.length === 0) {
      const li = document.createElement('li');
      li.textContent = 'None (Plain Cheese)';
      summaryToppings.appendChild(li);
    } else {
      toppings.forEach(top => {
        const li = document.createElement('li');
        li.textContent = `${top.value} (+$${TOPPING_PRICE.toFixed(2)})`;
        summaryToppings.appendChild(li);
      });
    }

    summaryTotal.textContent = `$${total.toFixed(2)}`;
    orderSummary.removeAttribute('hidden');
    orderSummary.scrollIntoView({ behavior: 'smooth' });
  });

  // Handle reset/re-order
  newOrderBtn.addEventListener('click', () => {
    orderSummary.setAttribute('hidden', '');
    form.reset();
    calculateTotal();
    drawPixelPizza();
  });

  // Initial calculation and canvas render
  calculateTotal();
  drawPixelPizza();
});
